import os
from pathlib import Path
# Check process environments for the named variable, without revealing any value.
found=[]; errors=[]
for d in Path('/proc').iterdir():
    if not d.name.isdigit(): continue
    f=d/'environ'
    try:
        vals=f.read_bytes().split(b'\0')
        if any(v.startswith(b'SHOPIFY_API_SECRET=') for v in vals): found.append(d.name)
    except Exception as e:
        errors.append((d.name,type(e).__name__))
print('processes with SHOPIFY_API_SECRET:', found)
print('unreadable process environments:', errors)
# Check for exact variable name in regular files outside system package trees.
roots=['/inputs','/work','/home','/run','/tmp','/opt','/srv','/mnt','/media']
hits=[]
for root in roots:
    p=Path(root)
    if not p.exists(): continue
    for f in p.rglob('*'):
        try:
            if f.is_file() and f.stat().st_size <= 5_000_000 and b'SHOPIFY_API_SECRET' in f.read_bytes(): hits.append(str(f))
        except Exception:
            pass
print('files containing variable name:', hits)
